1	import { join, dirname } from 'node:path';
2	import { finding } from '../../../../../engine/checks/helpers/findings.mjs';
3	import { matchingLines, ruleIdsIn } from '../../../../../engine/checks/helpers/line-scanning.mjs';
4	
5	// A pack's injected prose must not narrate its own enforcement: checks run on
6	// their own at every Stop and in CI, and each failure message carries its
7	// rule. Scans exactly the file each pack.mjs declares as `prose`, never the
8	// pack README — the catalog convention *requires* the README to list the
9	// pack's rules and how each is enforced. Home-only by declaration:
10	// canon-curation is declared solely in the canon home repo, which gates this
11	// rule for free.
12	const RUNNER = /checks\/run\.mjs/;
13	const asWord = (id) => new RegExp(`(^|[^\\w-])${id}([^\\w-]|$)`); // never inside a longer kebab name
14	
15	const rule = {
16	  id: 'pack-no-enforcement-narration',
17	  severity: 'blocking',
18	  description: "A pack's injected prose neither tells the reader to run the checks runner nor names the rules the pack's own checks enforce",
19	  doc: 'engine/checks/DESIGN.md',
20	  why: 'checks run automatically at every Stop and in CI, and each failure message carries its rule — prose narrating its own enforcement duplicates the mechanism and drifts from it',
21	
22	  run(ctx) {
23	    const docs = ctx.files
24	      .filter((f) => /^packs\/[^/]+\/pack\.mjs$/.test(f))
25	      .flatMap((f) => {
26	        const m = /\bprose:\s*'([^']+)'/.exec(ctx.read(f) ?? '');
27	        return m ? [join(dirname(f), m[1])] : [];
28	      });
29	    return [
30	      ...matchingLines(ctx, docs, RUNNER).map(({ file, line }) => finding(rule, {
31	        file, line,
32	        what: 'tells the reader to run the checks runner',
33	        fix: 'delete the instruction — the Stop hook and CI run every check on their own',
34	      })),
35	      ...docs.flatMap((doc) => [...ruleIdsIn(ctx, dirname(doc))].sort().flatMap((id) =>
36	        matchingLines(ctx, [doc], asWord(id)).map(({ file, line }) => finding(rule, {
37	          file, line,
38	          what: `names its own check rule "${id}"`,
39	          fix: 'remove the mention — the rule announces itself when it fires, and its failure message carries the instruction',
40	        })))),
41	    ];
42	  },
43	};
44	
45	export default rule;
46

