import json, sys, subprocess

FILES = sys.argv[1:]

CORRECTION_KEYWORDS = [
    "no,", "no —", "actually", "i meant", "not what i", "that's wrong", "that is wrong",
    "instead of", "misunderstood", "misread", "correction", "sorry", "you're right",
    "you are right", "revert", "undo that", "wrong", "don't do that", "stop,",
    "wait,", "hold on", "let me clarify", "to clarify", "i should have",
]

def is_human_text_block(entry):
    # A 'user' role entry whose content is plain text (not tool_result) -> real human typed message
    if entry.get("type") != "user":
        return None
    msg = entry.get("message", {})
    if msg.get("role") != "user":
        return None
    content = msg.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        texts = []
        for c in content:
            if isinstance(c, dict) and c.get("type") == "text":
                texts.append(c.get("text", ""))
        if texts:
            return "\n".join(texts)
    return None

def is_assistant_text(entry):
    if entry.get("type") != "assistant":
        return None
    msg = entry.get("message", {})
    if msg.get("role") != "assistant":
        return None
    content = msg.get("content")
    if isinstance(content, list):
        texts = []
        for c in content:
            if isinstance(c, dict) and c.get("type") == "text":
                texts.append(c.get("text", ""))
        if texts:
            return "\n".join(texts)
    return None

for f in FILES:
    print(f"\n===== FILE: {f} =====")
    out = subprocess.run(["git", "show", f"origin/conversation-logs:{f}"], capture_output=True, text=True, cwd="/home/user/Claudinite")
    lines = out.stdout.splitlines()
    prev_ts = None
    human_count = 0
    for line in lines:
        if not line.strip():
            continue
        try:
            entry = json.loads(line)
        except Exception:
            continue
        ts = entry.get("timestamp")
        ht = is_human_text_block(entry)
        if ht is not None and ht.strip():
            human_count += 1
            low = ht.lower()
            hit = [k for k in CORRECTION_KEYWORDS if k in low]
            flag = f" [FLAG:{hit}]" if hit else ""
            print(f"  HUMAN @ {ts}{flag}: {ht[:400]!r}")
        # detect AskUserQuestion tool use
        if entry.get("type") == "assistant":
            msg = entry.get("message", {})
            content = msg.get("content")
            if isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get("type") == "tool_use" and c.get("name") == "AskUserQuestion":
                        print(f"  ASKUSERQUESTION @ {ts}: {json.dumps(c.get('input'))[:400]}")
    if human_count == 0:
        print("  (no human-typed text turns found — likely an unattended/automated run)")

import json, sys

path = sys.argv[1]
with open(path) as fh:
    lines = fh.readlines()

for i, line in enumerate(lines):
    line = line.strip()
    if not line:
        continue
    try:
        e = json.loads(line)
    except Exception:
        continue
    ts = e.get("timestamp", "")
    typ = e.get("type")
    if typ == "user":
        msg = e.get("message", {})
        content = msg.get("content")
        if isinstance(content, str):
            print(f"[{i}] {ts} USER-TEXT: {content[:300]!r}")
        elif isinstance(content, list):
            for c in content:
                if not isinstance(c, dict):
                    continue
                if c.get("type") == "text":
                    print(f"[{i}] {ts} USER-TEXT: {c.get('text','')[:300]!r}")
                elif c.get("type") == "tool_result":
                    cont = c.get("content")
                    if isinstance(cont, list):
                        s = " ".join(x.get("text","") for x in cont if isinstance(x, dict))
                    else:
                        s = str(cont)
                    print(f"[{i}] {ts} TOOL-RESULT: {s[:200]!r}")
    elif typ == "assistant":
        msg = e.get("message", {})
        content = msg.get("content")
        if isinstance(content, list):
            for c in content:
                if not isinstance(c, dict):
                    continue
                if c.get("type") == "text":
                    print(f"[{i}] {ts} ASSISTANT-TEXT: {c.get('text','')[:300]!r}")
                elif c.get("type") == "tool_use":
                    print(f"[{i}] {ts} TOOL-USE {c.get('name')}: {json.dumps(c.get('input'))[:200]}")

